import re
# Get all project_info data
df_info = conn_proj.execute("SELECT Project_Information, Licenses FROM project_info").fetchdf()
print(df_info.shape)

def extract_project_name(text):
    # Look for pattern like "owner/repo" with allowed chars
    m = re.search(r'\b([A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+)\b', text)
    return m.group(1) if m else None

def extract_forks(text):
    # Look for "X forks" possibly with commas
    m = re.search(r'([\d,]+)\s+forks', text)
    if m:
        return int(m.group(1).replace(',', ''))
    m = re.search(r'forks count of ([\d,]+)', text)
    if m:
        return int(m.group(1).replace(',', ''))
    m = re.search(r'forked ([\d,]+) times', text)
    if m:
        return int(m.group(1).replace(',', ''))
    return None

df_info['ProjectName'] = df_info['Project_Information'].apply(extract_project_name)
df_info['Forks'] = df_info['Project_Information'].apply(extract_forks)
print(df_info[['ProjectName','Forks','Licenses']].head(10))
print("Null forks:", df_info['Forks'].isna().sum())
print("Null projname:", df_info['ProjectName'].isna().sum())

# Improve fork extraction to capture "1 fork"
def extract_forks(text):
    # all patterns
    patterns = [
        r'([\d,]+)\s+forks?\b',
        r'forks?\s+count\s+of\s+([\d,]+)',
        r'forked\s+([\d,]+)\s+times',
    ]
    for p in patterns:
        m = re.search(p, text)
        if m:
            return int(m.group(1).replace(',', ''))
    return None

df_info['Forks'] = df_info['Project_Information'].apply(extract_forks)
print("Null forks:", df_info['Forks'].isna().sum())
print(df_info[df_info['Forks'].isna()]['Project_Information'].values[:5])
